function csrf_field():string{return'<input type="hidden" name="csrf_token" value="'.e(AuthService::csrfToken()).'">';}
function game_time(int $seconds):string{if($seconds>=86400){$days=intdiv($seconds,86400);return$days.'d '.gmdate('H:i:s',$seconds%86400);}if($seconds>=3600)return gmdate('G:i:s',$seconds);return gmdate('i:s',$seconds);}
function ordinal_word(int $number):string{$words=[1=>'first',2=>'second',3=>'third',4=>'fourth',5=>'fifth',6=>'sixth',7=>'seventh'];return$words[$number]??($number.(in_array($number%100,[11,12,13],true)?'th':([1=>'st',2=>'nd',3=>'rd'][$number%10]??'th')));}
function story_moment(int $seconds,int $duration):string{if($duration<86400)return game_time($seconds);$seconds=min(max(0,$seconds),max(0,$duration-1));$day=intdiv($seconds,86400)+1;$hour=(int)gmdate('G',$seconds%86400);$part=$hour<5?'late at night':($hour<12?'sometime in the morning':($hour<17?'sometime in the afternoon':($hour<22?'sometime in the evening':'late at night')));return'On the '.ordinal_word($day).' day, '.$part;}
function story_phase_label(string $phase):string{return['EXPOSITION'=>'The Story Begins','INCITING_INCIDENT'=>'Trouble Emerges','RISING_ACTION'=>'Pressure Builds','CLIMAX'=>'The Decisive Moment','RESOLUTION'=>'Consequences Settle','COMPLETE'=>'Consequences Settle'][$phase]??ucwords(strtolower(str_replace('_',' ',$phase)));}
function story_phase_for_second(int $second,int $duration):string{$ratio=$duration>0?$second/$duration:1;return$ratio<.18?'EXPOSITION':($ratio<.42?'INCITING_INCIDENT':($ratio<.72?'RISING_ACTION':($ratio<.92?'CLIMAX':'RESOLUTION')));}
function personal_experience_label(string $type):string{return['DECISION'=>'What You Did','NO_ACTION'=>'What You Left Undone','LOCATION'=>'Where You Went','KNOWLEDGE'=>'What You Learned','CONSEQUENCE'=>'What Changed for You','INTERACTION'=>'What You Considered','EXPERIENCED'=>'Your Point of View'][$type]??'Your Point of View';}
function timeline_fingerprint(string $text):string{$text=mb_strtolower(strip_tags($text));$text=preg_replace('/[^\p{L}\p{N}]+/u',' ',$text);return trim((string)$text);}
function player_visible_text(string $text):string{$text=preg_replace('/\\s*Final factors:\\s*[^.!?]+[.!?]?/ui','',$text);$text=preg_replace('/\s*(?:Location|Goal|Fear)\s*→\s*[^.!?]+[.!?]?/ui','',$text);$text=preg_replace('/(^|[.!?]\s+|\n\s*)(?:ACHIEVED|FAILED|RESOLVED|ACTIVE|INACTIVE)(\s*[:·\-–—]\s*|\s*[.!?](?=\s|$))/u','$1',$text);$sentences=preg_split('/(?<=[.!?])\s+/u',trim((string)$text))?:[];$sentences=array_values(array_filter($sentences,static fn($sentence)=>!preg_match('/\d+\s*→\s*\d+/u',$sentence)&&!preg_match('/^[A-Z][A-Z0-9_]*\s*=\s*[^.!?]+[.!?]?$/u',trim($sentence))&&mb_strtolower(trim($sentence))!=='knowledge changed.'));return trim(implode(' ',$sentences));}
function missed_opportunity_text(array $labels):string{$labels=array_values(array_filter(array_map(static fn($label)=>lcfirst(rtrim(trim((string)$label),'.')),$labels)));if(!$labels)return'You were given a chance to act, but the moment passed before you could act.';$last=array_pop($labels);$choices=$last??'act';if($labels)$choices=implode(', ',$labels).(count($labels)>1?', or ':' or ').$choices;return'You were given the chance to '.$choices.', but the moment passed before you could act — the situation changed.';}
