color:var(--background);background-image:var(--background-image);background-size:cover;background-attachment:fixed}#game-live h1{font-family:var(--title-font)!important;color:var(--title-color)!important;font-size:var(--title-size)!important;font-weight:var(--title-weight)!important;text-decoration:var(--title-decoration)!important}#game-live h2,#game-live h3,#game-live .phase-divider,#game-live .cast-person h3,#game-live .timeline-entry h3{font-family:var(--heading-font)!important;color:var(--heading-color)!important;font-size:var(--heading-size)!important;font-weight:var(--heading-weight)!important;text-decoration:var(--heading-decoration)!important}#game-live p,#game-live .timeline-entry p{font-family:var(--body-font)!important;color:var(--ink)!important;font-size:var(--body-size)!important;font-weight:var(--body-weight)!important;text-decoration:var(--body-decoration)!important}#game-live .muted,#game-live .timeline-time,#game-live .entry-label,#game-live small,#game-live .live-note{font-family:var(--meta-font)!important;color:var(--meta-color)!important;font-size:var(--meta-size)!important;font-weight:var(--meta-weight)!important;text-decoration:var(--meta-decoration)!important}#game-live .btn,#game-live button,#game-live .option{font-family:var(--button-font)!important;color:var(--button-color)!important;font-size:var(--button-size)!important;font-weight:var(--button-weight)!important;text-decoration:var(--button-decoration)!important}.bar{background:var(--secondary)}.card{background-color:color-mix(in srgb,var(--surface) 94%,transparent);background-image:var(--card-image);background-position:center;background-repeat:repeat;background-size:cover;background-blend-mode:soft-light;border-color:color-mix(in srgb,var(--primary) 22%,#ddd)}.current-item{border-color:var(--accent)}.current-item b,.phase-divider,.entry-label,.timeline-entry p strong{color:var(--primary)}.decision{border-color:var(--primary);background:color-mix(in srgb,var(--primary) 8%,var(--surface))