id="narrator-enable"> Enable narration</span></label><label class="narrator-field">Voice<select id="narrator-voice"></select></label><label class="narrator-field"><span><input type="checkbox" id="narrator-autoplay"> Play new story text automatically</span></label><label class="narrator-field"><span><input type="checkbox" id="narrator-wait"> Wait for me before the next part</span></label><label class="narrator-field">Speed <input type="range" id="narrator-rate" min="0.5" max="2" step="0.05" value="1"> <span id="narrator-rate-val">1×</span></label><label class="narrator-field">Volume <input type="range" id="narrator-volume" min="0" max="1" step="0.05" value="1"> <span id="narrator-volume-val">100%</span></label></div><div class="narrator-actions"><button type="button" class="btn" id="narrator-read-now">Read now</button><button type="button" class="btn" id="narrator-stop">Stop</button><button type="button" class="btn" id="narrator-continue" hidden>Continue</button><button type="button" class="btn" id="narrator-retell" hidden>Tell the whole story</button></div><p class="narrator-status muted" id="narrator-status">Narration off.</p><p class="muted" style="font-size:13px">The narrator reads the story aloud on this device. Voices are open-source (Kokoro, Apache 2.0) and load the first time you enable narration. Your choices are saved on this device only — each player picks their own voice.</p></details></div><?php endif;?><div id="game-live" data-status="<?=e($sim['status'])?>" data-divider-image="<?=(!empty($theme['divider_media_id'])||!empty($theme['divider_image_path']))?'1':'0'?>"><main class="shell" aria-live="polite"><a class="game-close" href="./" aria-label="Back to My Games" title="Back to My Games">‹ Back to My Games</a><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><?php if($rated):?><p class="card">Thank you for rating this story.</p><?php endif;?>
<?php if($sim['status']==='COMPLETE'):?><section class="card outcome"><h1>The Story Is Complete</h1><?php if($endingFragments):?><?php foreach($endingFragments as$fragment):?><div class="ending-fragment"><?php foreach($fragment['images'] as$endingImage):?><img class="story-image" src="<?=e($endingImage['file_path'])?>" alt="<?=e($endingImage['alt_text'])?>"><?php if(!empty($endingImage['caption_text'])):?><p class="story-image-caption"><?=e($endingImage['caption_text'])?></p><?php endif;?><?php endforeach;?><h3><?=e($fragment['section_label'])?></h3><p><?=nl2br(e($fragment['text']))?></p></div><?php endforeach;?><?php else:?><?php if($endingImages):?><?php foreach($endingImages as$endingImage):?><img class="story-image" src="<?=e($endingImage['file_path'])?>" alt="<?=e($endingImage['alt_text'])?>"><?php if(!empty($endingImage['caption_text'])):?><p class="story-image-caption"><?=e($endingImage['caption_text'])?></p><?php endif;?><?php endforeach;?><?php elseif($endingMedia):?><img class="story-image" src="<?=e($endingMedia['file_path'])?>" alt="<?=e($endingMedia['alt_text'])?>"><?php if(!empty($endingMedia['caption_text'])):?><p class="story-image-caption"><?=e($endingMedia['caption_text'])?></p><?php endif;?><?php endif;?><?php if($epilogue):?><p><?=nl2br(e($epilogue))?></p><?php else:?><p>The immediate crisis has ended, but its consequences are only beginning.</p><?php endif;?><?php endif;?></section><?php endif;?>
<section class="card briefing"><small>Your Story Briefing</small><h1>The Situation</h1><?php if($openingMedia):?><img class="story-image" src="<?=e($openingMedia['file_path'])?>" alt="<?=e($openingMedia['alt_text'])?>"><?php if(!empty($openingMedia['caption_text'])):?><p class="story-image-caption"><?=e($openingMedia['caption_text'])?></p><?php endif;?><?php endif;?><p><?=e((string)($sim['scenario_text']?:($sim['title'].' takes place in '.$sim['setting_name'].'.')))?></p><?php if($character):?><p><b>You Are <?=e($character['name'])?>.</b> <?=e($character['description'])?></p><?php endif;?></section>
<section class="mobile-context"><?php if($character):?><details data-persist-key="character"><summary>You Are <?=e($character['name'])?> · <?=e($character['current_location'])?></summary><?php if($characterMedia):?><img class="story-image character" src="<?=e($characterMedia['file_path'])?>" alt="<?=e($characterMedia['alt_text']??($character['name'].' portrait'))?>"><?php endif;?><p><b>Your Current Goal:</b> <?=e($character['goal_text'])?></p><p><?=e($character['description'])?></p></details><details data-persist-key="situation"><summary>Review the Situation</summary><p><?=e((string)($sim['scenario_text']?:($sim['title'].' takes place in '.$sim['setting_name'].'.')))?> </p></details><details data-persist-key="stakes"><summary>Your Personal Stakes</summary><p><b>Your Fear:</b> <?=e($character['fear_text'])?></p><p><b>What Only You Know:</b> <?=e($character['private_knowledge'])?></p></details><details data-persist-key="cast"><summary>People in This Story</summary><?php foreach($otherCharacters as$other):?><div class="mobile-cast-person"><?php if(isset($characterPortraits[(int)$other['character_id']])):?><img class="cast-portrait" src="<?=e($characterPortraits[(int)$other['character_id']]['file_path'])?>" alt=""><?php endif;?><p><b><?=e($other['name'])?></b><br><?=e($other['description'])?></p></div><?php endforeach;?></details><?php endif;?></section>

<div class="layout"><div><?php if($character&&$sim['status']!=='COMPLETE'):?><section class="card now-card"><div class="now-head"><h2>Now</h2><span class="muted"><?=e(story_phase_label(story_phase_for_second((int)$sim['elapsed_seconds'],$storyDuration)))?> &middot; <?=e(story_moment($displaySecond((int)$sim['elapsed_seconds']),$playDuration))?></span></div><?php $nowEvent=null;foreach($snap['world']as$w){if(($w['event_type']??'')==='WORLD')$nowEvent=$w;}$nowImage=null;if($nowEvent){$nowBucket=$sceneMedia[(int)($nowEvent['event_second']??-1)]??[];if($nowBucket)$nowImage=$nowBucket[0];}if($nowImage):?><img class="story-image" src="<?=e($nowImage['file_path'])?>" alt="<?=e($nowImage['alt_text'])?>"><?php if(!empty($nowImage['caption_text'])):?><p class="story-image-caption"><?=e($nowImage['caption_text'])?></p><?php endif;?><?php endif;?><?php if($nowEvent):?><p class="now-event"><strong><?=e((string)$nowEvent['headline'])?></strong> <?=e(player_visible_text((string)$nowEvent['event_text']))?></p><?php endif;?><?php if(!empty($character['open_decisions'])):?><?php foreach($character['open_decisions']as$d):?><div class="now-decision"><span class="decision-alert">Decision Available</span><h3>Choose What You Do</h3><p><?=e($d['prompt_text'])?></p><?php $left=(int)($d['closes_at_second']??0)-(int)$sim['elapsed_seconds'];if($left>0):?><p class="now-count">About <?=e(game_time(max(1,(int)round($left*$playDuration/max(1,$storyDuration))))) ?> left to decide</p><?php endif;?><?php foreach($d['options']as$o):?><form method="post"><?=csrf_field()?><input type="hidden" name="game_id" value="<?=$gid?>"><input type="hidden" name="action" value="decide"><input type="hidden" name="decision_id" value="<?=(int)$d['decision_id']?>"><input type="hidden" name="option_code" value="<?=e($o['option_code'])?>"><button class="option"><b><?=e($o['label'])?></b><?php if(!empty($o['description'])):?><br><small><?=e($o['description'])?></small><?php endif;?></button></form><?php endforeach;?></div><?php endforeach;?><?php else:?><p class="muted">No decision right now — the story is unfolding. New moments will be added to the end of your story below as they happen.</p><?php endif;?></section><?php endif;?><section class="card story-card"><h2>Your Story So Far</h2><p class="live-note">The story in the order it happened. Each chapter brings together what happened around you and what your character personally experienced.</p><?php if(!$timeline):?><p class="muted">The story is beginning…</p><?php endif;?><div class="timeline"><?php $shownPhase=null;foreach($timeline as$second=>$row):$both=!empty($row['public'])&&!empty($row['personal']);if($shownPhase!==$row['phase']):$shownPhase=$row['phase'];?><h3 class="phase-divider"><?=e(story_phase_label((string)$shownPhase))?></h3><?php endif;?><article class="timeline-row"><div class="timeline-time"><?=e(story_moment($displaySecond((int)$second),$playDuration))?></div><?php foreach($sceneMedia[(int)$second]??[] as$sceneImage):?><img class="story-image" src="<?=e($sceneImage['file_path'])?>" alt="<?=e($sceneImage['alt_text'])?>"><?php if(!empty($sceneImage['caption_text'])):?><p class="story-image-caption"><?=e($sceneImage['caption_text'])?></p><?php endif;?><?php endforeach;?><div class="timeline-pair <?=$both?'':'solo'?>"><?php if($row['public']):?><div><?php foreach($row['public']as$item):?><section class="timeline-entry"><p><strong><?=e($item['lead'])?></strong> <?=e($item['detail'])?></p></section><?php endforeach;?></div><?php endif;?><?php if($row['personal']):?><div><?php foreach($row['personal']as$item):?><section class="timeline-entry personal"><div class="entry-label"><?=e($item['label'])?></div><h3><?=e($item['title'])?></h3><p><?=e($item['detail'])?></p></section><?php endforeach;?></div><?php endif;?></div></article><?php endforeach;?></div></section></div><aside>
<?php if($character):?><section class="card private"><small>You Are Playing</small><h2><?=e($character['name'])?></h2><?php if($characterMedia):?><img class="story-image character" src="<?=e($characterMedia['file_path'])?>" alt="<?=e($characterMedia['alt_text'])?>"><?php endif;?><p><?=e($character['description'])?></p><div class="current-position"><div class="current-item"><b>Your Current Location</b><?=e($character['current_location'])?></div><div class="current-item"><b>Your Current Goal</b><?=e($character['goal_text'])?></div></div></section>
<section class="card stakes"><h2>Your Personal Stakes</h2><p><b>Your Fear:</b> <?=e($character['fear_text'])?></p><p><b>What Only You Know:</b> <?=e($character['private_knowledge'])?></p></section>
<?php if(!empty($snap['factors'])):?><section class="card"><h2>Story State</h2><div class="cast-list"><?php foreach($snap['factors']as$f):?><p style="margin:0"><b><?=e($f['label'])?></b> — <?=(int)$f['current_value']?><?php if(isset($factorLastChange[(string)$f['factor_code']])):$fc=$factorLastChange[(string)$f['factor_code']];?><br><small class="muted"><?=$fc['new_value']>$fc['old_value']?'Rose':'Fell'?> from <?=(int)$fc['old_value']?> to <?=(int)$fc['new_value']?></small><?php endif;?></p><?php endforeach;?></div></section><?php endif;?>
<?php if($standings):?><section class="card"><h2><?=e($standingsTitle)?></h2><div class="cast-list"><?php foreach($standings as$srow):?><p style="margin:0"><b><?=e($srow['name'])?></b> — <?=(int)$srow['current_value']?></p><?php endforeach;?></div></section><?php endif;?>
<section class="card"><h2>People in This Story</h2><div class="cast-list"><?php foreach($otherCharacters as$other):$hasPortrait=isset($characterPortraits[(int)$other['character_id']]);?><article class="cast-person <?=$hasPortrait?'':'no-portrait'?>"><?php if($hasPortrait):?><img class="cast-portrait" src="<?=e($characterPortraits[(int)$other['character_id']]['file_path'])?>" alt="<?=e($characterPortraits[(int)$other['character_id']]['alt_text'])?>"><?php endif;?><div><h3><?=e($other['name'])?></h3><p><?=e($other['description'])?></p></div></article><?php endforeach;?></div></section>
<?php else:?><section class="card"><h2>Spectator View</h2><p>You did not select a character before the game began.</p></section><?php endif;?>
<?php if($sim['status']==='COMPLETE'):?><section class="card"><h2>Rate This Story</h2><form method="post"><?=csrf_field()?><input type="hidden" name="game_id" value="<?=$gid?>"><input type="hidden" name="action" value="rate"><label>Rating <select name="rating"><?php for($i=5;$i>=1;$i--):?><option value="<?=$i?>"><?=$i?> / 5</option><?php endfor;?></select></label><p><textarea name="review" rows="4" style="width:100%" placeholder="Optional review"></textarea></p><button class="btn">Save Rating</button></form></section><?php endif;?></aside></div></main></div>
<?php if(NarratorService::enabled()):?><script src="assets/toinky-narrator.js" defer></script><?php endif;?><script>let liveBusy=false,liveTimer=null;const accordionKey='toinky-accordions-<?=$gid?>';function accordionState(root=document){const state={};root.querySelectorAll('details[data-persist-key]').forEach(d=>state[d.dataset.persistKey]=d.open);return state}function saveAccordions(root=document){sessionStorage.setItem(accordionKey,JSON.stringify(accordionState(root)))}function restoreAccordions(root=document,state=null){try{state=state||JSON.parse(sessionStorage.getItem(accordionKey)||'{}')}catch(e){state={}}root.querySelectorAll('details[data-persist-key]').forEach(d=>{if(Object.hasOwn(state,d.dataset.persistKey))d.open=!!state[d.dataset.persistKey];d.addEventListener('toggle',()=>saveAccordions(root))})}restoreAccordions();async function refreshLiveGame(){if(liveBusy||document.hidden)return;liveBusy=true;try{const current=document.querySelector('#game-live'),state=accordionState(current),scroll=window.scrollY;const response=await fetch('play.php?game=<?=$gid?>&live=1',{cache:'no-store',headers:{'X-Toinky-Live':'1'}});if(!response.ok)return;const html=await response.text();const next=new DOMParser().parseFromString(html,'text/html').querySelector('#game-live');if(next&&current){current.replaceWith(next);restoreAccordions(next,state);window.scrollTo(0,scroll);if(next.dataset.status!=='RUNNING'&&liveTimer){clearInterval(liveTimer);liveTimer=null;}}}catch(error){}finally{liveBusy=false;}}if(document.querySelector('#game-live')?.dataset.status==='RUNNING'){liveTimer=setInterval(refreshLiveGame,2000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshLiveGame();});}</script></body></html>
